     1	/* SPDX-License-Identifier: LGPL-2.1-or-later */
     2	
     3	#ifndef __NM_LLDP_NEIGHBOR_H__
     4	#define __NM_LLDP_NEIGHBOR_H__
     5	
     6	#include "nm-lldp-rx.h"
     7	
     8	struct _NMLldpNeighbor {
     9	    NMLldpNeighborID id;
    10	
    11	    /* Neighbor objects stay around as long as they are linked into an "NMLldpRX" object or n_ref > 0. */
    12	    struct _NMLldpRX *lldp_rx;
    13	
    14	    gint64 timestamp_usec;
    15	
    16	    gint64 until_usec;
    17	
    18	    int      ref_count;
    19	    unsigned prioq_idx;
    20	
    21	    NMEtherAddr source_address;
    22	    NMEtherAddr destination_address;
    23	
    24	    /* The raw packet size. The data is appended to the object, accessible via LLDP_NEIGHBOR_RAW() */
    25	    size_t raw_size;
    26	
    27	    /* The current read index for the iterative TLV interface */
    28	    size_t rindex;
    29	
    30	    /* And a couple of fields parsed out. */
    31	    bool has_ttl : 1;
    32	    bool has_capabilities : 1;
    33	    bool has_port_vlan_id : 1;
    34	
    35	    uint16_t ttl;
    36	
    37	    uint16_t system_capabilities;
    38	    uint16_t enabled_capabilities;
    39	
    40	    char *port_description;
    41	    char *system_name;
    42	    char *system_description;
    43	    char *mud_url;
    44	
    45	    uint16_t port_vlan_id;
    46	
    47	    char *chassis_id_as_string;
    48	    char *port_id_as_string;
    49	};
    50	
    51	static inline void *
    52	NM_LLDP_NEIGHBOR_RAW(const NMLldpNeighbor *n)
    53	{
    54	    return (uint8_t *) n + NM_ALIGN(sizeof(NMLldpNeighbor));
    55	}
    56	
    57	static inline uint8_t
    58	NM_LLDP_NEIGHBOR_TLV_TYPE(const NMLldpNeighbor *n)
    59	{
    60	    return ((uint8_t *) NM_LLDP_NEIGHBOR_RAW(n))[n->rindex] >> 1;
    61	}
    62	
    63	static inline size_t
    64	NM_LLDP_NEIGHBOR_TLV_LENGTH(const NMLldpNeighbor *n)
    65	{
    66	    uint8_t *p;
    67	
    68	    p = (uint8_t *) NM_LLDP_NEIGHBOR_RAW(n) + n->rindex;
    69	    return p[1] + (((size_t) (p[0] & 1)) << 8);
    70	}
    71	
    72	static inline void *
    73	NM_LLDP_NEIGHBOR_TLV_DATA(const NMLldpNeighbor *n)
    74	{
    75	    return ((uint8_t *) NM_LLDP_NEIGHBOR_RAW(n)) + n->rindex + 2;
    76	}
    77	
    78	int nm_lldp_neighbor_prioq_compare_func(const void *a, const void *b);
    79	
    80	void            nm_lldp_neighbor_unlink(NMLldpNeighbor *n);
    81	NMLldpNeighbor *nm_lldp_neighbor_new(size_t raw_size);
    82	int             nm_lldp_neighbor_parse(NMLldpNeighbor *n);
    83	void            nm_lldp_neighbor_start_ttl(NMLldpNeighbor *n);
    84	
    85	#endif /* __NM_LLDP_NEIGHBOR_H__ */
